class Solution:
    def sortColors(self, nums: List[int]) -> None:
        lo, i, hi = 0, 0, len(nums) - 1     # [0,lo) 是 0，[lo,i) 是 1，(hi,end] 是 2
        while i <= hi:
            if nums[i] == 0:
                nums[lo], nums[i] = nums[i], nums[lo]
                lo += 1
                i += 1
            elif nums[i] == 2:
                nums[i], nums[hi] = nums[hi], nums[i]
                hi -= 1                     # 换过来的数还没看过，i 不动
            else:
                i += 1

class Solution:
    def sortColors(self, nums: List[int]) -> None:
        p0 = p1 = 0                         # 下一个 0、下一个 1 该写的位置
        for i, x in enumerate(nums):
            nums[i] = 2
            if x < 2:
                nums[p1] = 1
                p1 += 1
            if x == 0:
                nums[p0] = 0
                p0 += 1

